package allocator

import (
	"testing"

	"github.com/stretchr/testify/require"
)

func TestCountBits(t *testing.T) {
	tests := []struct {
		name     string
		input    *big.Int
		expected int
	}{
		{
			name:     "zero",
			input:    &big.Int{0},
			expected: 0,
		},
		{
			name:     "one",
			input:    &big.Int{1},
			expected: 1,
		},
		{
			name:     "two",
			input:    &big.Int{2},
			expected: 1,
		},
		{
			name:     "three",
			input:    &big.Int{3},
			expected: 2,
		},
		{
			name:     "four",
			input:    &big.Int{4},
			expected: 1,
		},
		{
			name:     "eight",
			input:    &big.Int{8},
			expected: 1,
		},
		{
			name:     "fifteen",
			input:    &big.Int{15},
			expected: 4,
		},
		{
			name:     "zeroes",
			input:    &big.Int{0, 0, 0, 0, 0, 0, 0, 0},
			expected: 0,
		},
		{
			name:     "ones",
			input:    &big.Int{1, 1, 1, 1, 1, 1, 1, 1},
			expected: 8,
		},
		{
			name:     "mixed",
			input:    &big.Int{1, 0, 1, 0, 1, 0, 1, 0},
			expected: 4,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			actual := countBits(test.input)
			require.Equal(t, test.expected, actual)
		})
	}
}

